// Collect all GitHub activity for the repo in the past week
const item = $input.first().json;
const repo = item.repo || 'owner/repo';
const token = item.githubToken || '';
const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
const headers = {
  'Accept': 'application/vnd.github.v3+json',
  'User-Agent': 'WeeklyDevSummaryBot'
};
if (token) headers['Authorization'] = `Bearer ${token}`;

const api = async (path) => {
  const url = `https://api.github.com/repos/${repo}/${path}`;
  const res = await this.helpers.httpRequest({
    url,
    method: 'GET',
    headers,
    json: true
  });
  return Array.isArray(res) ? res : [];
};

// Fetch all three data sources in parallel
const [commits, issues, prs] = await Promise.all([
  api(`commits?per_page=20&since=${encodeURIComponent(since)}`),
  api(`issues?state=closed&per_page=20&since=${encodeURIComponent(since)}&filter=all`),
  api(`pulls?state=closed&sort=updated&direction=desc&per_page=20`)
]);

// Filter PRs to only merged ones from this week
const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
const mergedPrs = prs.filter(p => p.merged_at && new Date(p.merged_at).getTime() > weekAgo);

// Filter issues to exclude pull requests
const closedIssues = issues.filter(i => !i.pull_request);

return [{
  json: {
    repo,
    channel: item.channel || '#dev-updates',
    language: item.language || 'EN',
    claudeApiKey: item.claudeApiKey,
    slackWebhook: item.slackWebhook || '',
    commitCount: commits.length,
    commits: commits.map(c => ({
      message: c.commit.message.split('\n')[0],
      author: c.commit.author.name,
      date: c.commit.author.date,
      url: c.html_url
    })),
    issueCount: closedIssues.length,
    issues: closedIssues.slice(0, 20).map(i => ({
      title: i.title,
      author: i.user?.login,
      url: i.html_url
    })),
    prCount: mergedPrs.length,
    prs: mergedPrs.slice(0, 20).map(p => ({
      title: p.title,
      author: p.user?.login,
      url: p.html_url
    }))
  }
}];

// Build a prompt for Claude from collected GitHub data
const data = $input.first().json;
const lang = (data.language || 'EN').toUpperCase();

const format = (items) => items.map(i => `- ${i.title || i.message} (${i.author || 'unknown'})`).join('\n');

const repo = data.repo;
const isFrench = lang === 'FR';

const prompt = isFrench
  ? `Résumé hebdomadaire — ${repo}\n\n` +
    `Commits (${data.commitCount}) :\n${format(data.commits)}\n\n` +
    `Problèmes fermés (${data.issueCount}) :\n${format(data.issues)}\n\n` +
    `PRs fusionnées (${data.prCount}) :\n${format(data.prs)}\n\n` +
    `Génère un résumé narratif en français organisé par thème. ` +
    `Mets en évidence les changements significatifs, les tendances et les domaines nécessitant une attention particulière.`
  : `Weekly development summary — ${repo}\n\n` +
    `Commits (${data.commitCount}):\n${format(data.commits)}\n\n` +
    `Closed issues (${data.issueCount}):\n${format(data.issues)}\n\n` +
    `Merged PRs (${data.prCount}):\n${format(data.prs)}\n\n` +
    `Generate a narrative summary organized by theme. ` +
    `Highlight significant changes, trends, and areas needing attention.`;

return [{
  json: {
    prompt,
    repo: data.repo,
    channel: data.channel,
    language: data.language,
    claudeApiKey: data.claudeApiKey,
    slackWebhook: data.slackWebhook,
    commitCount: data.commitCount,
    issueCount: data.issueCount,
    prCount: data.prCount
  }
}];

