const textBlock = content.find(c => c.type === 'text');
const summary = textBlock?.text || 'No summary generated.';

return [{
  json: {
    summary,
    repo: $json.repo,
    channel: $json.channel,
    slackWebhook: $json.slackWebhook,
    commitCount: $json.commitCount,
    issueCount: $json.issueCount,
